payload.template:
{{- /* scripts/alert_routing.py (#34): one notification -> one GitHub dispatch */ -}}
{{- $a := index .Alerts 0 -}}
{{- if .Alerts.Firing }}{{ $a = index .Alerts.Firing 0 }}{{ end -}}
{{- $env := $a.Labels.environment -}}
{{- $alert := $a.Labels.alert -}}
{{- $grafana := reReplaceAll "/*$" "/" .ExternalURL -}}
{{- $from := printf "%d" ($a.StartsAt.Add -1800000000000).UnixMilli -}}
{{- $to := "now" -}}
{{- $resolvedAt := "" -}}
{{- if eq $a.Status "resolved" -}}
  {{- $to = printf "%d" ($a.EndsAt.Add 600000000000).UnixMilli -}}
  {{- $resolvedAt = $a.EndsAt.UTC.Format "2006-01-02T15:04:05Z" -}}
{{- end -}}
{{- $traceql := printf `{resource.service.name="ineedtofocus" && resource.deployment.environment.name="%s" && kind=server && span.http.route=~"/api/sessions|/api/sessions/sync" && status=error}` $env -}}
{{- if eq $alert "history-latency" }}{{ $traceql = printf `{resource.service.name="ineedtofocus" && resource.deployment.environment.name="%s" && kind=server && span.http.route="/api/history" && duration > 1s}` $env }}{{ end -}}
{{- $tempo := coll.Dict "type" "tempo" "uid" "grafanacloud-traces" -}}
{{- $query := coll.Dict "refId" "A" "datasource" $tempo "queryType" "traceql"
  "query" $traceql "limit" 20 "tableType" "traces" -}}
{{- $range := coll.Dict "from" $from "to" $to -}}
{{- $panes := coll.Dict "alert" (coll.Dict
  "datasource" "grafanacloud-traces" "queries" (coll.Slice $query) "range" $range) -}}
{{- $runbook := $a.Annotations.runbook_url -}}
{{- if not $runbook }}{{ $runbook = printf "https://github.com/ybenzine/ineedtofocus/blob/main/_docs/runbooks/%s.md" $alert }}{{ end -}}
{{- /* A contact point test has no rule behind it: link the alert list instead. */ -}}
{{- $rule := $a.GeneratorURL -}}
{{- if not (match "^https?://" $rule) -}}
  {{- $search := printf "label:alert=%s label:environment=%s" $alert $env -}}
  {{- $rule = printf "%salerting/list?search=%s" $grafana (urlquery $search) -}}
{{- end -}}
{{- $dashboard := printf "%sd/focus-key-journey-%s?orgId=1&from=%s&to=%s"
  $grafana $env $from $to -}}
{{- $traces := printf "%sexplore?schemaVersion=1&orgId=1&panes=%s"
  $grafana (urlquery ($panes | data.ToJSON)) -}}
{{- coll.Dict
  "event_type" "grafana-alert"
  "client_payload" (coll.Dict
    "alert" $alert
    "environment" $env
    "status" $a.Status
    "title" $a.Labels.alertname
    "summary" $a.Annotations.summary
    "description" $a.Annotations.description
    "started_at" ($a.StartsAt.UTC.Format "2006-01-02T15:04:05Z")
    "resolved_at" $resolvedAt
    "links" (coll.Dict
      "dashboard" $dashboard
      "traces" $traces
      "runbook" $runbook
      "alert" $rule))
  | data.ToJSON -}}
